export const QUELLTEXTE: Readonly<Record<string, string>> = {
  "projects/beispiel-app/src/index.html": "<!doctype html>\n<html lang=\"de\" class=\"z-root\">\n  <head>\n    <meta charset=\"utf-8\" />\n    <!-- zenit-theme-init: the output of zenitThemeInitScript({ defaultScheme: 'system' }), the same config as\n         provideZenitTheme() in app.config.ts. It sets data-theme and data-accent before\n         the first paint; ZTheme only gets to it after bootstrap, a few frames late.\n         Generated, not written: a test in projects/zenit-ui/schematics compares it. -->\n    <!-- prettier-ignore -->\n    <script>(function(k,S,A,ds,da){var s=ds,a=da,d=document.documentElement,m=function(q,f){try{return matchMedia(q).matches}catch(e){return f}};try{var v=JSON.parse((k&&localStorage.getItem(k))||'null');if(v&&typeof v==='object'){if(v.scheme==='system'||S.indexOf(v.scheme)>-1)s=v.scheme;if(A.indexOf(v.accent)>-1)a=v.accent}}catch(e){}if(s==='system')s=S.indexOf('contrast')>-1&&m('(prefers-contrast: more)',false)?'contrast':m('(prefers-color-scheme: dark)',true)?'dark':'light';d.setAttribute('data-theme',s);if(a!==da)d.setAttribute('data-accent',a)})(\"zenit-theme\",[\"dark\",\"light\",\"contrast\"],[\"rot\",\"blau\",\"gruen\",\"violett\"],\"system\",\"rot\")</script>\n    <title>Gameserver · Zenit-Hosting Beispiel</title>\n    <base href=\"/\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n    <link rel=\"icon\" type=\"image/x-icon\" href=\"favicon.ico\" />\n  </head>\n  <!-- z-root belongs on <html> and on <body> (README, step 2): it carries\n       background, text color, the three fonts, `font: inherit` for controls and\n       the focus ring. Overlays (dialog, menu, toast) attach to <body> and\n       inherit the same custom properties from there. -->\n  <body class=\"z-root\">\n    <app-root></app-root>\n  </body>\n</html>\n",
  "projects/beispiel-app/src/styles.css": "/* #region schriften */\n/* Fonts, self-hosted, exactly as step 3 of the package README describes them:\n   Material Icons for z-icon, Inter 400/500/600 as body, Space Grotesk 600/700\n   as display, JetBrains Mono 400/600 as mono. No request to Google.\n   The cascade layer is required: material-icons sets its own font-size on\n   .material-icons and is loaded after zenit-ui.css, so without the layer the\n   icon would be 24px inside a 20px box. */\n@import 'material-icons/iconfont/filled.css' layer(schriften);\n@import '@fontsource/inter/400.css';\n@import '@fontsource/inter/500.css';\n@import '@fontsource/inter/600.css';\n@import '@fontsource/space-grotesk/600.css';\n@import '@fontsource/space-grotesk/700.css';\n@import '@fontsource/jetbrains-mono/400.css';\n@import '@fontsource/jetbrains-mono/600.css';\n/* #endregion */\n\n/* Everything below is the whole stylesheet of this application. The building\n   blocks bring their own classes, so an application only spaces the regions of\n   the page and styles what the library has no block for: the code display of\n   this example. Values come from tokens.css only, no hex, no pixel literals,\n   no radius of its own. */\n\n/* Skip link: the library's .z-visually-hidden holds it out of sight, so the\n   1px box is not written a second time here; this rule only places it and\n   unfolds it into a real 40px target above the header once it takes focus\n   (15-zustaende.md, \"Tastatur\"). */\n.app-skip {\n  left: var(--space-4);\n  top: var(--space-4);\n  z-index: var(--z-header);\n}\n.app-skip:focus {\n  display: inline-flex;\n  align-items: center;\n  width: auto;\n  height: auto;\n  margin: 0;\n  min-height: var(--control-md);\n  padding: 0 var(--space-3);\n  border-radius: var(--radius-sm);\n  background: var(--surface-raised);\n  clip-path: none;\n}\n\n/* The content area between header and footer. */\n.app-main {\n  display: block;\n  padding-block: var(--space-6) var(--space-9);\n}\n\n/* Customer area (CLAUDE.md, \"Abstand und Layout\"): PageHeader, then space-6,\n   then the panels, which keep space-5 between them through .z-stack. */\n.app-page {\n  display: grid;\n  gap: var(--space-6);\n}\n\n/* Filter row: search and status select in one line, from 640px on, with the\n   select at sidebar width (Select README). Below that they stack, so nothing\n   scrolls sideways at 360px. */\n.app-filter {\n  display: grid;\n  gap: var(--space-3);\n  align-items: end;\n  grid-template-columns: minmax(0, 1fr);\n}\n@media (min-width: 640px) {\n  .app-filter {\n    grid-template-columns: minmax(0, 1fr) var(--sidebar);\n  }\n}\n\n/* Column head above the amounts. The cells themselves get their alignment and\n   the mono face from [zRowNum]; the head keeps the caption style of the row\n   head and only moves to the right. */\n.app-rechts {\n  text-align: right;\n}\n\n/* Sections of the page \"Einbindung\": a heading, a sentence, a code block,\n   separated by a 1px line instead of a frame (CLAUDE.md, \"Rahmen nur um\n   Werkzeuge\"). */\n.app-abschnitt {\n  display: grid;\n  gap: var(--space-4);\n  padding-top: var(--space-6);\n  border-top: 1px solid var(--border);\n}\n.app-abschnitt h2,\n.app-abschnitt p {\n  margin: 0;\n  max-width: var(--measure);\n}\n\n/* Disclosure over a code block. Same shape as z-faq, but a native details, so\n   that a <pre> is allowed inside it (z-faq projects into a <p>). */\n.app-code-faq {\n  border-top: 1px solid var(--border);\n}\n.app-code-faq > summary {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: var(--space-4);\n  min-height: var(--control-md);\n  padding-block: var(--space-2);\n  color: var(--text-muted);\n  font-weight: 500;\n  cursor: pointer;\n  list-style: none;\n}\n.app-code-faq > summary::-webkit-details-marker {\n  display: none;\n}\n.app-code-faq > summary::after {\n  content: '+';\n  font-family: var(--font-mono);\n}\n.app-code-faq[open] > summary::after {\n  content: '−';\n}\n.app-code-faq[open] > summary {\n  color: var(--text);\n}\n\n/* Several blocks inside one disclosure. */\n.app-code-gruppe {\n  display: grid;\n  gap: var(--space-5);\n  padding-bottom: var(--space-4);\n}\n\n/* Code block: caption line, then the framed area. */\n.app-code {\n  display: grid;\n  gap: var(--space-2);\n  margin: 0;\n  min-width: 0;\n}\n.app-code__kopf {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  justify-content: space-between;\n  gap: var(--space-2);\n}\n.app-code__datei {\n  color: var(--text-subtle);\n}\n/* The only element of the page that may scroll sideways, capped in height so\n   that a long file does not push everything else off the screen. */\n.app-code__flaeche {\n  max-height: calc(var(--space-9) * 4);\n  overflow: auto;\n  border: 1px solid var(--border);\n  border-radius: var(--radius-md);\n  background: var(--bg);\n}\n.app-code__text {\n  margin: 0;\n  padding: var(--space-4);\n}\n",
  "projects/beispiel-app/src/main.ts": "import { bootstrapApplication } from '@angular/platform-browser';\nimport { appConfig } from './app/app.config';\nimport { App } from './app/app';\n\nbootstrapApplication(App, appConfig).catch((err) => console.error(err));\n",
  "projects/beispiel-app/src/app/app.config.ts": "import { ApplicationConfig, provideBrowserGlobalErrorListeners } from '@angular/core';\nimport { provideRouter, withComponentInputBinding } from '@angular/router';\nimport { provideZenitTheme } from 'zenit-ui';\nimport { routes } from './app.routes';\n\nexport const appConfig: ApplicationConfig = {\n  providers: [\n    provideBrowserGlobalErrorListeners(),\n    // withComponentInputBinding() hands query parameters to matching component\n    // inputs. That is how `?zustand=laden` reaches the page without the page\n    // having to subscribe to the router.\n    provideRouter(routes, withComponentInputBinding()),\n    // #region theme\n    // Scheme and accent live in themes.css; the provider applies the stored or\n    // the default choice before the first frame and keeps it in localStorage.\n    // 'system' follows prefers-color-scheme until someone picks a scheme.\n    provideZenitTheme({ defaultScheme: 'system' }),\n    // Another language for the library's own texts would be:\n    // provideZenitLabels(Z_LABELS_EN),\n    // #endregion\n  ],\n};\n",
  "projects/beispiel-app/src/app/app.routes.ts": "import { Routes } from '@angular/router';\n\n/**\n * Two pages, both lazy. `/` redirects to the Gameserver list, which is the page\n * this example is about; `/einbindung` explains how it is wired.\n */\nexport const routes: Routes = [\n  { path: '', pathMatch: 'full', redirectTo: 'gameserver' },\n  {\n    path: 'gameserver',\n    loadComponent: () => import('./pages/gameserver/gameserver').then((m) => m.Gameserver),\n  },\n  {\n    path: 'einbindung',\n    loadComponent: () => import('./pages/einbindung/einbindung').then((m) => m.Einbindung),\n  },\n];\n",
  "projects/beispiel-app/src/app/layout/shell/shell.ts": "import { Component } from '@angular/core';\nimport { RouterLink, RouterLinkActive, RouterOutlet } from '@angular/router';\nimport {\n  ZAppHeader,\n  ZBrand,\n  ZFooter,\n  ZFooterBase,\n  ZHeaderEnd,\n  ZHeaderLink,\n  ZToastOutlet,\n} from 'zenit-ui';\nimport { GUTHABEN, KUNDEN_LINKS, NUTZER } from '../../gameserver/beispieldaten';\nimport { ThemeControl } from '../theme-control/theme-control';\n\n/**\n * Layout of the customer area: header, content, footer (10-seitenmuster.md,\n * \"Seite im Kundenbereich\"). Every page of a real application sits in here, so\n * the shell is the only place that knows about navigation, theme control and\n * toast outlet.\n */\n@Component({\n  selector: 'app-shell',\n  imports: [\n    RouterLink,\n    RouterLinkActive,\n    RouterOutlet,\n    ThemeControl,\n    ZAppHeader,\n    ZBrand,\n    ZFooter,\n    ZFooterBase,\n    ZHeaderLink,\n    ZHeaderEnd,\n    ZToastOutlet,\n  ],\n  template: `\n    <!-- First tab stop of the page, visible only while focused. -->\n    <a class=\"app-skip body-sm z-visually-hidden\" href=\"#inhalt\">Zum Hauptinhalt springen</a>\n\n    <!-- Header, content and footer share the same z-container, so brand,\n         page title and copyright stand on one line at every width. -->\n    <div class=\"z-container\">\n      <!-- #region kopfzeile -->\n      <z-app-header navLabel=\"Hauptnavigation\">\n        <!-- The logo file belongs to the repository of the real site; the design\n             system ships none, so the brand is its name in the display face. -->\n        <span zBrand>Zenit</span>\n        @for (link of links; track link.name) {\n          @if (link.route) {\n            <a\n              zHeaderLink\n              [routerLink]=\"link.route\"\n              routerLinkActive\n              #aktiv=\"routerLinkActive\"\n              [active]=\"aktiv.isActive\"\n              >{{ link.name }}</a\n            >\n          } @else {\n            <!-- The other pages of the customer area are not part of this\n                 example. They stay links so the header keeps its real shape. -->\n            <a zHeaderLink href=\"#\" (click)=\"$event.preventDefault()\">{{ link.name }}</a>\n          }\n        }\n        <!-- Credit in mono without a red pill, and a link to the billing page\n             (AppHeader README). The label says what the number is and where the\n             link goes, because \"25,00 €\" alone says nothing when read out loud;\n             the amount comes from the same value the link shows, so the two\n             cannot drift apart. -->\n        <a\n          zHeaderLink\n          zHeaderEnd\n          class=\"z-mono\"\n          href=\"#\"\n          [attr.aria-label]=\"'Guthaben ' + guthaben + ', zur Abrechnung'\"\n          (click)=\"$event.preventDefault()\"\n          >{{ guthaben }}</a\n        >\n        <!-- Colour scheme and accent, see layout/theme-control. -->\n        <app-theme-control zHeaderEnd />\n        <!-- Decorative: the name is already in the account menu of a real app. -->\n        <span zHeaderEnd class=\"z-avatar\" aria-hidden=\"true\">{{ nutzer }}</span>\n      </z-app-header>\n      <!-- #endregion -->\n    </div>\n\n    <!-- tabindex=\"-1\" lets the skip link move the focus here. z-container keeps\n         the content at most the container width and left aligned. -->\n    <main id=\"inhalt\" tabindex=\"-1\" class=\"z-container app-main\">\n      <router-outlet />\n    </main>\n\n    <div class=\"z-container\">\n      <!-- #region fusszeile -->\n      <z-footer>\n        <!-- Customer area: only the bottom row, copyright left and the legal\n             links right, no link columns (Footer README). Both parts carry\n             zFooterBase, because the row spreads its own children. -->\n        <span zFooterBase>© 2026 Zenit-Hosting</span>\n        <span zFooterBase class=\"z-cluster\">\n          @for (link of rechtliches; track link) {\n            <a href=\"#\" (click)=\"$event.preventDefault()\">{{ link }}</a>\n          }\n        </span>\n      </z-footer>\n      <!-- #endregion -->\n    </div>\n\n    <!-- #region toastauslass -->\n    <!-- Once per application, at the end of the layout (README, step 4). -->\n    <z-toast-outlet />\n    <!-- #endregion -->\n  `,\n})\nexport class Shell {\n  protected readonly guthaben = GUTHABEN;\n  protected readonly nutzer = NUTZER;\n  protected readonly links = KUNDEN_LINKS;\n  protected readonly rechtliches = ['Impressum', 'Datenschutz', 'AGB', 'Widerruf'];\n}\n",
  "projects/beispiel-app/src/app/layout/theme-control/theme-control.ts": "import { CdkMenuTrigger } from '@angular/cdk/menu';\nimport { Component, computed, inject } from '@angular/core';\nimport { ZButton, ZIcon, ZMenu, ZMenuItem, ZTheme } from 'zenit-ui';\n\n/** The schemes of `themes.css` plus the one that follows the operating system. */\nconst SCHEMATA = [\n  { id: 'dark', name: 'Dunkel', icon: 'dark_mode' },\n  { id: 'light', name: 'Hell', icon: 'light_mode' },\n  { id: 'contrast', name: 'Kontrast', icon: 'contrast' },\n  { id: 'system', name: 'System', icon: 'brightness_auto' },\n] as const;\n\n/** The four accents of `accents.css`. `rot` is the default and carries no attribute. */\nconst AKZENTE = [\n  { id: 'rot', name: 'Rot' },\n  { id: 'blau', name: 'Blau' },\n  { id: 'gruen', name: 'Grün' },\n  { id: 'violett', name: 'Violett' },\n] as const;\n\n/**\n * Colour scheme and accent, for the end slot of the header.\n *\n * Two menus instead of two `z-select`s: a select needs a visible label and a\n * width of its own, and at 360px the header already carries brand, menu\n * button, credit and avatar. An icon button is 40px on mobile and says its\n * current value in its `aria-label`, so nothing is lost. The menus come from\n * the library, the state from `ZTheme`, which also stores it in\n * `localStorage`; this component holds none of its own.\n */\n@Component({\n  selector: 'app-theme-control',\n  imports: [CdkMenuTrigger, ZButton, ZIcon, ZMenu, ZMenuItem],\n  host: { class: 'z-cluster' },\n  template: `\n    <button\n      zBtn=\"ghost\"\n      size=\"sm\"\n      iconOnly\n      type=\"button\"\n      [attr.aria-label]=\"'Farbschema wählen, aktuell ' + schemaName()\"\n      [cdkMenuTriggerFor]=\"schemaMenue\"\n    >\n      <z-icon [name]=\"schemaIcon()\" />\n    </button>\n    <ng-template #schemaMenue>\n      <z-menu>\n        @for (schema of schemata; track schema.id) {\n          <button\n            zMenuItem\n            [icon]=\"schema.icon\"\n            [attr.aria-current]=\"schema.id === theme.scheme() ? 'true' : null\"\n            (triggered)=\"theme.setScheme(schema.id)\"\n          >\n            {{ schema.name }}\n          </button>\n        }\n      </z-menu>\n    </ng-template>\n\n    <button\n      zBtn=\"ghost\"\n      size=\"sm\"\n      iconOnly\n      type=\"button\"\n      [attr.aria-label]=\"'Akzentfarbe wählen, aktuell ' + akzentName()\"\n      [cdkMenuTriggerFor]=\"akzentMenue\"\n    >\n      <z-icon name=\"palette\" />\n    </button>\n    <ng-template #akzentMenue>\n      <z-menu>\n        @for (akzent of akzente; track akzent.id) {\n          <button\n            zMenuItem\n            [attr.aria-current]=\"akzent.id === theme.accent() ? 'true' : null\"\n            (triggered)=\"theme.setAccent(akzent.id)\"\n          >\n            {{ akzent.name }}\n          </button>\n        }\n      </z-menu>\n    </ng-template>\n  `,\n})\nexport class ThemeControl {\n  protected readonly theme = inject(ZTheme);\n  protected readonly schemata = SCHEMATA;\n  protected readonly akzente = AKZENTE;\n\n  /** German name of the chosen scheme, for the label of the trigger. */\n  protected readonly schemaName = computed(\n    () => SCHEMATA.find((s) => s.id === this.theme.scheme())?.name ?? this.theme.scheme(),\n  );\n\n  /**\n   * Icon of the chosen scheme. In system mode it shows what is applied right\n   * now, so the button never claims a scheme the page is not in.\n   */\n  protected readonly schemaIcon = computed(() => {\n    const gewaehlt = SCHEMATA.find((s) => s.id === this.theme.scheme());\n    return gewaehlt?.id === 'system' || !gewaehlt\n      ? (SCHEMATA.find((s) => s.id === this.theme.resolvedScheme())?.icon ?? 'brightness_auto')\n      : gewaehlt.icon;\n  });\n\n  protected readonly akzentName = computed(\n    () => AKZENTE.find((a) => a.id === this.theme.accent())?.name ?? this.theme.accent(),\n  );\n}\n",
  "projects/beispiel-app/src/app/pages/gameserver/gameserver.ts": "import { Clipboard } from '@angular/cdk/clipboard';\nimport {\n  Component,\n  computed,\n  inject,\n  input,\n  linkedSignal,\n  resource,\n  signal,\n  viewChild,\n} from '@angular/core';\nimport { form, FormField } from '@angular/forms/signals';\nimport { firstValueFrom } from 'rxjs';\nimport {\n  ZButton,\n  ZDialog,\n  ZField,\n  ZIcon,\n  ZInput,\n  ZInputGroup,\n  ZPageHeader,\n  ZSelect,\n  ZToast,\n} from 'zenit-ui';\nimport { BeispielServer, STATUS_FILTER } from '../../gameserver/beispieldaten';\nimport {\n  filtern,\n  GameserverData,\n  ListenZustand,\n  Simulation,\n  SKELETT_MS,\n  warte,\n} from '../../gameserver/gameserver-data';\nimport { ServerList } from '../../gameserver/server-list/server-list';\nimport { CodeBlock } from '../../shared/code-block/code-block';\nimport { DATEI, quelltext } from '../../shared/quelltexte';\n\n/** The states a reader can call up through `?zustand=`. */\nconst SIMULATIONEN: readonly Simulation[] = ['normal', 'laden', 'leer', 'fehler'];\n\n/** The filter that narrows nothing down: no text, \"Alle Status\". */\nconst KEIN_FILTER = { suche: '', status: STATUS_FILTER[0] };\n\n/**\n * Page \"Gameserver\" of the customer area (10-seitenmuster.md): AppHeader,\n * PageHeader with one fact and one action, then the panels. The page title is\n * the same word as the navigation link.\n *\n * It owns the load, the filter, the feedback and the confirmation; drawing the\n * list is the job of ServerList. State is signals throughout: the query\n * parameter is an input, the list a `resource()`, the filter a Signal Form\n * (docs/signals.md).\n *\n * Every region carries a disclosure with its own source. A native `details` and\n * not `z-faq`, because that component projects into a `<p>` limited to\n * `measure`, and a `<pre>` inside a `<p>` is invalid HTML that the parser\n * closes early. `nav[zTabs]` with \"Vorschau | Code\" was the alternative; it\n * would show the code by default and put a second interactive layer on every\n * region of a page whose job is to be looked at. A closed `details` stays out\n * of the way, needs no script and is keyboard operable by itself.\n */\n@Component({\n  selector: 'app-gameserver',\n  imports: [\n    CodeBlock,\n    FormField,\n    ServerList,\n    ZButton,\n    ZField,\n    ZIcon,\n    ZInput,\n    ZInputGroup,\n    ZPageHeader,\n    ZSelect,\n  ],\n  host: { class: 'app-page' },\n  template: `\n    <!-- #region seitenkopf -->\n    <!-- One fact, and the one primary of this screen (PageHeader README). -->\n    <z-page-header title=\"Gameserver\" sub=\"Abrechnung nach Stunden, nächste Rechnung am 01.10.2026\">\n      <button zBtn=\"primary\" type=\"button\" (click)=\"erstellen()\">\n        <z-icon name=\"add\" />\n        Server erstellen\n      </button>\n    </z-page-header>\n    <!-- #endregion -->\n\n    <details class=\"app-code-faq\">\n      <summary>So ist es eingebunden: Seitenkopf</summary>\n      <app-code-block\n        [code]=\"quellen.seitenkopf\"\n        datei=\"pages/gameserver/gameserver.ts\"\n        sprache=\"Template\"\n      />\n    </details>\n\n    <div class=\"z-stack\">\n      @if (filterSichtbar()) {\n        <!-- #region filterzeile -->\n        <!-- An empty list shows no filters (EmptyState README), so the row only\n             exists while there is something to narrow down. -->\n        <div class=\"app-filter\">\n          <z-field label=\"Suche\" for=\"suche\">\n            <z-input-group icon=\"search\">\n              <input\n                zInput\n                size=\"sm\"\n                id=\"suche\"\n                type=\"search\"\n                placeholder=\"Name oder Adresse\"\n                [formField]=\"filter.suche\"\n              />\n            </z-input-group>\n          </z-field>\n          <z-field label=\"Status\" for=\"status\">\n            <z-select size=\"sm\">\n              <select id=\"status\" [formField]=\"filter.status\">\n                @for (option of statusOptionen; track option) {\n                  <option [value]=\"option\">{{ option }}</option>\n                }\n              </select>\n            </z-select>\n          </z-field>\n        </div>\n        <!-- #endregion -->\n\n        <details class=\"app-code-faq\">\n          <summary>So ist es eingebunden: Filterzeile</summary>\n          <div class=\"app-code-gruppe\">\n            <app-code-block\n              [code]=\"quellen.filterzeile\"\n              datei=\"pages/gameserver/gameserver.ts\"\n              sprache=\"Template\"\n            />\n            <app-code-block\n              [code]=\"quellen.filter\"\n              datei=\"pages/gameserver/gameserver.ts\"\n              sprache=\"TypeScript\"\n            />\n          </div>\n        </details>\n      }\n\n      <!-- #region liste -->\n      <app-server-list\n        [server]=\"gefiltert()\"\n        [zustand]=\"zustandDerListe()\"\n        (oeffnen)=\"oeffnen($event)\"\n        (kopieren)=\"adresseKopieren($event)\"\n        (neustart)=\"neustart($event)\"\n        (loeschen)=\"loeschen($event)\"\n        (erstellen)=\"erstellen()\"\n        (filterZuruecksetzen)=\"filterZuruecksetzen()\"\n        (erneutLaden)=\"erneutLaden()\"\n      />\n      <!-- #endregion -->\n\n      <details class=\"app-code-faq\">\n        <summary>So ist es eingebunden: Serverliste mit allen Zuständen</summary>\n        <div class=\"app-code-gruppe\">\n          <app-code-block\n            [code]=\"quellen.liste\"\n            datei=\"pages/gameserver/gameserver.ts\"\n            sprache=\"Template\"\n          />\n          <app-code-block\n            [code]=\"quellen.laden\"\n            datei=\"pages/gameserver/gameserver.ts\"\n            sprache=\"TypeScript\"\n          />\n          <app-code-block\n            [code]=\"quellen.dienst\"\n            datei=\"gameserver/gameserver-data.ts\"\n            sprache=\"TypeScript\"\n          />\n          <app-code-block\n            [code]=\"quellen.zustaende\"\n            datei=\"gameserver/server-list/server-list.ts\"\n            sprache=\"Template\"\n          />\n          <app-code-block\n            [code]=\"quellen.zeile\"\n            datei=\"gameserver/server-list/server-list.ts\"\n            sprache=\"Template\"\n          />\n          <app-code-block\n            [code]=\"quellen.seitenwahl\"\n            datei=\"gameserver/server-list/server-list.ts\"\n            sprache=\"Template\"\n          />\n        </div>\n      </details>\n\n      <details class=\"app-code-faq\">\n        <summary>So ist es eingebunden: Aktionen mit Toast und Dialog</summary>\n        <app-code-block\n          [code]=\"quellen.aktionen\"\n          datei=\"pages/gameserver/gameserver.ts\"\n          sprache=\"TypeScript\"\n        />\n      </details>\n\n      <details class=\"app-code-faq\">\n        <summary>So ist es eingebunden: Rahmen und Theme-Umschalter</summary>\n        <div class=\"app-code-gruppe\">\n          <app-code-block\n            [code]=\"quellen.kopfzeile\"\n            datei=\"layout/shell/shell.ts\"\n            sprache=\"Template\"\n          />\n          <app-code-block\n            [code]=\"quellen.themeUmschalter\"\n            datei=\"layout/theme-control/theme-control.ts\"\n            sprache=\"TypeScript\"\n          />\n        </div>\n      </details>\n    </div>\n  `,\n})\nexport class Gameserver {\n  private readonly daten = inject(GameserverData);\n  private readonly toast = inject(ZToast);\n  private readonly dialog = inject(ZDialog);\n  private readonly clipboard = inject(Clipboard);\n\n  /** The list, asked to move the focus when a row disappears under it. */\n  private readonly listenElement = viewChild.required(ServerList);\n\n  /**\n   * Query parameter `?zustand=laden|leer|fehler`, handed over by the router\n   * through `withComponentInputBinding()`. Anything else shows the normal list.\n   */\n  readonly zustand = input<string>();\n\n  protected readonly statusOptionen = STATUS_FILTER;\n\n  /**\n   * The code the disclosures show, read once from the generated copy of the\n   * real files. Nothing here is written by hand, so the page cannot show code\n   * that the page does not run.\n   */\n  protected readonly quellen = {\n    seitenkopf: quelltext(DATEI.seite, 'seitenkopf'),\n    filterzeile: quelltext(DATEI.seite, 'filterzeile'),\n    filter: quelltext(DATEI.seite, 'filter'),\n    liste: quelltext(DATEI.seite, 'liste'),\n    laden: quelltext(DATEI.seite, 'laden'),\n    dienst: quelltext(DATEI.daten, 'laden'),\n    aktionen: quelltext(DATEI.seite, 'aktionen'),\n    zustaende: quelltext(DATEI.liste, 'zustaende'),\n    zeile: quelltext(DATEI.liste, 'zeile'),\n    seitenwahl: quelltext(DATEI.liste, 'seitenwahl'),\n    kopfzeile: quelltext(DATEI.shell, 'kopfzeile'),\n    themeUmschalter: quelltext(DATEI.themeControl),\n  };\n\n  // #region laden\n  /**\n   * What the server answers. It follows the query parameter and stays writable,\n   * which is what `linkedSignal()` is for: \"Erneut laden\" asks for the normal\n   * answer, so that the simulated error can be left again, and a new parameter\n   * wins over that choice.\n   */\n  private readonly simulation = linkedSignal<Simulation>(\n    () => SIMULATIONEN.find((s) => s === this.zustand()) ?? 'normal',\n  );\n\n  /**\n   * The list is a `resource()`: new params start a load and abort the running\n   * one, a rejected loader is the error state, and no effect or subscription\n   * pushes the answer into a signal. A real page calls `liste.reload()` to\n   * try again.\n   */\n  private readonly liste = resource<readonly BeispielServer[], Simulation>({\n    params: () => this.simulation(),\n    loader: ({ params, abortSignal }) => this.daten.laden(params, abortSignal),\n    defaultValue: [],\n  });\n\n  /**\n   * Turns true once a load has taken longer than 300 milliseconds, and only\n   * then does the list draw skeleton rows (15-zustaende.md, \"Lädt\"). The delay\n   * is a resource as well: it starts with the load, and the end of the load\n   * aborts it and puts it back to `false`.\n   */\n  private readonly dauertLange = resource({\n    params: () => this.liste.isLoading() || undefined,\n    loader: ({ abortSignal }) => warte(SKELETT_MS, abortSignal).then(() => true),\n    defaultValue: false,\n  });\n\n  /** `value()` of a resource throws in the error state, hence the guard. */\n  private readonly server = computed(() => (this.liste.hasValue() ? this.liste.value() : []));\n\n  protected erneutLaden(): void {\n    this.simulation.set('normal');\n  }\n  // #endregion\n\n  // #region filter\n  /**\n   * The filter is a Signal Form: one signal holds the values, `form()` turns\n   * it into a field tree, and `[formField]` binds a native control to one\n   * field. No handler reads `$event.target`, and the filtered list is a\n   * `computed()` over the same signal.\n   */\n  protected readonly filterWerte = signal(KEIN_FILTER);\n  protected readonly filter = form(this.filterWerte);\n\n  protected readonly gefiltert = computed(() => {\n    const { suche, status } = this.filterWerte();\n    return filtern(this.server(), suche, status);\n  });\n\n  protected filterZuruecksetzen(): void {\n    // reset() with a value writes the model and clears touched and dirty.\n    this.filter().reset(KEIN_FILTER);\n  }\n  // #endregion\n\n  /** Every state of the list, derived from the two resources and the filter. */\n  protected readonly zustandDerListe = computed<ListenZustand>(() => {\n    if (this.liste.isLoading()) {\n      return this.dauertLange.value() ? 'skelett' : 'start';\n    }\n    if (this.liste.error()) {\n      return 'fehler';\n    }\n    if (this.server().length === 0) {\n      return 'leer';\n    }\n    return this.gefiltert().length === 0 ? 'gefiltert-leer' : 'liste';\n  });\n\n  /** An empty list shows no filters. */\n  protected readonly filterSichtbar = computed(() => this.server().length > 0);\n\n  /** The wizard belongs to the real application; here it only says so. */\n  protected erstellen(): void {\n    this.toast.show('Der Assistent gehört in deine Anwendung', { icon: 'info' });\n  }\n\n  /** Same for the detail page the row links to; this example has one page. */\n  protected oeffnen(server: BeispielServer): void {\n    this.toast.show(`Die Seite zu ${server.name} gehört in deine Anwendung`, { icon: 'info' });\n  }\n\n  protected adresseKopieren(server: BeispielServer): void {\n    this.clipboard.copy(server.adresse);\n    this.toast.show('Adresse kopiert', { icon: 'content_copy' });\n  }\n\n  // #region aktionen\n  /**\n   * Restart needs no dialog (Dialog README). The feedback is a toast: one\n   * sentence, no full stop, in the past participle.\n   */\n  protected neustart(server: BeispielServer): void {\n    this.toast.success(`Neustart für ${server.name} gestartet`);\n  }\n\n  /**\n   * Deleting cannot be undone, so it goes through a confirmation that asks for\n   * the server name.\n   *\n   * `restoreFocusTo` names the menu button of the row by its id, so cancelling\n   * and Escape put the focus back there even though the menu has already\n   * closed and taken the CDK's own memory of the trigger with it. After a\n   * confirmed delete that button no longer exists, so the list is told first\n   * where the focus goes instead; without that it would fall to `<body>`.\n   */\n  protected async loeschen(server: BeispielServer): Promise<void> {\n    // confirm() answers exactly once with an Observable<boolean>. One value is\n    // a promise, so the page awaits it and holds no subscription.\n    const bestaetigt = await firstValueFrom(\n      this.dialog.confirm({\n        title: `Server \"${server.name}\" löschen?`,\n        body: 'Alle Welten, Backups und Zugänge gehen verloren. Das lässt sich nicht rückgängig machen.',\n        confirmLabel: 'Löschen',\n        cancelLabel: 'Abbrechen',\n        danger: true,\n        requireText: server.name,\n        requireLabel: 'Name des Servers',\n        restoreFocusTo: `#aktionen-${server.id}`,\n      }),\n    );\n    if (bestaetigt) {\n      this.listenElement().fokusNachEntfernen(server);\n      // Writing to a resource puts it into the state 'local'. Deleting the\n      // last server leaves the list empty.\n      this.liste.update((alt) => alt.filter((eintrag) => eintrag.id !== server.id));\n      this.toast.success(`${server.name} gelöscht`);\n    }\n  }\n  // #endregion\n}\n",
  "projects/beispiel-app/src/app/gameserver/gameserver-data.ts": "import { Service } from '@angular/core';\nimport { BEISPIEL_SERVER, BeispielServer, STATUS_FILTER } from './beispieldaten';\n\n/**\n * Narrows the list: free text over name and address, plus one status. A pure\n * function, so the page keeps a `computed()` of one line and the rule can be\n * tested without a component.\n *\n * @param suche Free text, case is ignored. Empty means everything.\n * @param status One of {@link STATUS_FILTER}; the first entry means everything.\n */\nexport function filtern(\n  server: readonly BeispielServer[],\n  suche: string,\n  status: string,\n): readonly BeispielServer[] {\n  const text = suche.trim().toLowerCase();\n  return server.filter(\n    (eintrag) =>\n      (!text ||\n        eintrag.name.toLowerCase().includes(text) ||\n        eintrag.adresse.toLowerCase().includes(text)) &&\n      (status === STATUS_FILTER[0] || eintrag.statusText === status),\n  );\n}\n\n/**\n * What the page asks for, taken from the query parameter `?zustand=`. `normal`\n * is the default and shows the list.\n */\nexport type Simulation = 'normal' | 'laden' | 'leer' | 'fehler';\n\n/**\n * What the list renders. `start` is the first 300 milliseconds of a load:\n * nothing is drawn yet, because a fast answer must not make placeholders flash\n * (15-zustaende.md, \"Lädt\"). `gefiltert-leer` is a loaded list that the filter\n * narrows down to nothing.\n */\nexport type ListenZustand = 'start' | 'skelett' | 'liste' | 'leer' | 'fehler' | 'gefiltert-leer';\n\n/** Skeleton rows only after 300 milliseconds (15-zustaende.md, Skeleton README). */\nexport const SKELETT_MS = 300;\n\n/** Simulated answer of the server. */\nconst ANTWORT_MS = 600;\n\n/**\n * A timer as a promise that a `resource()` can abort: the abort clears the\n * timer and rejects, and the resource drops the result of an aborted load.\n */\nexport function warte(ms: number, abbruch: AbortSignal): Promise<void> {\n  return new Promise((fertig, abgebrochen) => {\n    const timer = setTimeout(fertig, ms);\n    abbruch.addEventListener(\n      'abort',\n      () => {\n        clearTimeout(timer);\n        abgebrochen(abbruch.reason);\n      },\n      { once: true },\n    );\n  });\n}\n\n/**\n * Source of the server list. In a real application this service calls the API;\n * here it answers from `beispieldaten.ts` after a timer. It holds no state:\n * the page wraps {@link laden} in a `resource()`, and loading, empty and error\n * are states of that resource instead of a switch in the template.\n *\n * `@Service()` is the short form of `@Injectable({ providedIn: 'root' })` for\n * singletons (Angular 22).\n */\n@Service()\nexport class GameserverData {\n  // #region laden\n  /**\n   * One load, shaped like the loader of a `resource()`: a promise that settles\n   * once and stops when `abbruch` fires. With `HttpClient` this method would\n   * be `firstValueFrom(http.get(...))`, or the page would use `httpResource()`.\n   *\n   * @param simulation `fehler` rejects, `leer` answers with no server and\n   *   `laden` never answers, so that the loading state can be looked at.\n   */\n  async laden(simulation: Simulation, abbruch: AbortSignal): Promise<readonly BeispielServer[]> {\n    if (simulation === 'laden') {\n      return new Promise<never>(() => undefined);\n    }\n    await warte(ANTWORT_MS, abbruch);\n    if (simulation === 'fehler') {\n      throw new Error('Simulated failure of the server list');\n    }\n    return simulation === 'leer' ? [] : BEISPIEL_SERVER;\n  }\n  // #endregion\n}\n",
  "projects/beispiel-app/src/app/gameserver/server-list/server-list.ts": "import { CdkMenuTrigger } from '@angular/cdk/menu';\nimport {\n  afterNextRender,\n  Component,\n  computed,\n  ElementRef,\n  inject,\n  Injector,\n  input,\n  linkedSignal,\n  output,\n} from '@angular/core';\nimport {\n  Z_MENU,\n  ZAlert,\n  ZAlertAction,\n  ZBadge,\n  ZButton,\n  ZEmptyAction,\n  ZEmptyState,\n  ZIcon,\n  ZPagination,\n  ZPanel,\n  ZRow,\n  ZRowAction,\n  ZRowLink,\n  ZRowMain,\n  ZRowMeta,\n  ZRowNum,\n  ZRows,\n  ZRowsHead,\n  ZRowTitle,\n  ZSkeleton,\n} from 'zenit-ui';\nimport { BeispielServer, euro } from '../beispieldaten';\nimport { ListenZustand } from '../gameserver-data';\n\n/** Rows per page. 25 is the default of z-pagination; eight servers need less. */\nconst PRO_SEITE = 6;\n\n/** Number of skeleton rows: as many as a normal answer brings (Skeleton README). */\nconst PLATZHALTER = [1, 2, 3];\n\n/**\n * The server list in all of its states. Presentational: it knows the servers\n * and the state, and it reports what the user wants; loading, deleting and\n * feedback stay in the page.\n *\n * The states come from 15-zustaende.md. Error is an alert instead of the panel,\n * because a page carries at most one alert and it stands above the content\n * (Alert README).\n */\n@Component({\n  selector: 'app-server-list',\n  imports: [\n    CdkMenuTrigger,\n    Z_MENU,\n    ZAlert,\n    ZAlertAction,\n    ZBadge,\n    ZButton,\n    ZEmptyAction,\n    ZEmptyState,\n    ZIcon,\n    ZPagination,\n    ZPanel,\n    ZRow,\n    ZRowAction,\n    ZRowLink,\n    ZRowMain,\n    ZRowMeta,\n    ZRowNum,\n    ZRows,\n    ZRowsHead,\n    ZRowTitle,\n    ZSkeleton,\n  ],\n  template: `\n    <!-- The live region stands in every state, so a screen reader announces the\n         sentence when it appears. aria-busy on the panel alone is silent, and\n         an aria-label on the roleless host of z-panel is ignored. -->\n    <p class=\"z-visually-hidden\" role=\"status\">\n      @if (zustand() === 'skelett') {\n        Server werden geladen\n      }\n    </p>\n    @if (zustand() === 'fehler') {\n      <!-- An error message names the cause and the next step; the one button\n           is secondary and small (Alert README). -->\n      <z-alert status=\"danger\" title=\"Die Serverliste ist nicht geladen\" icon=\"error\">\n        Das Panel hat nach 30 Sekunden nicht geantwortet. Lade die Liste neu oder öffne ein Ticket.\n        <button zAlertAction zBtn=\"secondary\" size=\"sm\" type=\"button\" (click)=\"erneutLaden.emit()\">\n          Erneut laden\n        </button>\n      </z-alert>\n    } @else {\n      <z-panel title=\"Meine Server\" flush [busy]=\"zustand() === 'skelett'\">\n        <!-- #region zustaende -->\n        @switch (zustand()) {\n          @case ('start') {\n            <!-- The first 300 milliseconds stay empty: an answer that fast must\n                 not make placeholders flash (15-zustaende.md). -->\n          }\n          @case ('skelett') {\n            <z-rows [columns]=\"spalten\">\n              <z-rows-head>\n                <span>Server</span>\n                <span>Status</span>\n                <span>Tarif</span>\n                <span class=\"app-rechts\">Bisher</span>\n                <span></span>\n              </z-rows-head>\n              <!-- Same grid, same row height: the layout must not jump when the\n                   data arrives (Skeleton README). -->\n              @for (platz of platzhalter; track platz) {\n                <div zRow>\n                  <span class=\"z-cluster\">\n                    <z-skeleton thumb />\n                    <z-skeleton width=\"120px\" />\n                  </span>\n                  <z-skeleton width=\"72px\" />\n                  <z-skeleton width=\"48px\" />\n                  <z-skeleton width=\"56px\" />\n                  <span></span>\n                </div>\n              }\n            </z-rows>\n          }\n          @case ('leer') {\n            <!-- The primary \"Server erstellen\" already sits in the PageHeader,\n                 so the same action is secondary here (EmptyState README). -->\n            <z-empty-state title=\"Du hast noch keinen Server\">\n              Der erste Server steht in etwa 60 Sekunden bereit.\n              <button zEmptyAction zBtn=\"secondary\" type=\"button\" (click)=\"erstellen.emit()\">\n                Server erstellen\n              </button>\n            </z-empty-state>\n          }\n          @case ('gefiltert-leer') {\n            <!-- Own sentence: the list is not empty, the filter is too narrow. -->\n            <z-empty-state title=\"Kein Server passt zum Filter\">\n              Ändere die Suche oder wähle wieder alle Status.\n              <button\n                zEmptyAction\n                zBtn=\"secondary\"\n                type=\"button\"\n                (click)=\"filterZuruecksetzen.emit()\"\n              >\n                Filter zurücksetzen\n              </button>\n            </z-empty-state>\n          }\n          @default {\n            <z-rows [columns]=\"spalten\">\n              <z-rows-head>\n                <span>Server</span>\n                <span>Status</span>\n                <span>Tarif</span>\n                <span class=\"app-rechts\">Bisher</span>\n                <span></span>\n              </z-rows-head>\n              @for (server of sichtbar(); track server.id) {\n                <!-- #region zeile -->\n                <!--\n                  A row that is a target and carries its own actions is a\n                  <div>: a <button> inside an <a> is invalid HTML and would\n                  give both controls one tab stop (15-zustaende.md,\n                  \"Tastatur\"). So the link sits on the title and carries\n                  zRowLink, whose stretched ::after makes the whole row\n                  clickable, and the menu button carries zRowAction, which\n                  lifts it above that overlay, keeps it a tab stop of its own\n                  and keeps it visible below 640px. In an application with a\n                  detail page the link is\n                  <a zRowTitle zRowLink [routerLink]=\"['/gameserver', server.id]\">;\n                  this example has only this one page and answers with a toast.\n                -->\n                <div zRow>\n                  <z-row-main [title]=\"server.name\">\n                    <a\n                      zRowTitle\n                      zRowLink\n                      href=\"#\"\n                      (click)=\"$event.preventDefault(); oeffnen.emit(server)\"\n                      >{{ server.name }}</a\n                    >\n                    <!-- Address and port in the mono face, the rest of the line\n                         in the body face (CLAUDE.md, \"Typografie\"). -->\n                    <div zRowMeta>\n                      {{ server.spiel }} ·\n                      <span class=\"z-mono\">{{ server.adresse }}</span>\n                      @if (server.hinweis) {\n                        · {{ server.hinweis }}\n                      }\n                    </div>\n                  </z-row-main>\n                  <!-- Status always in the second column, as a word plus dot. -->\n                  <span>\n                    <z-badge [status]=\"server.status\" dot>{{ server.statusText }}</z-badge>\n                  </span>\n                  <!-- Tariff is a tag: neutral, no dot (Badge README). -->\n                  <span\n                    ><z-badge>{{ server.tarif }}</z-badge></span\n                  >\n                  <!-- Amounts right aligned in mono with tabular figures. -->\n                  <span zRowNum>{{ preis(server) }}</span>\n                  <button\n                    zRowAction\n                    zBtn=\"ghost\"\n                    iconOnly\n                    type=\"button\"\n                    [id]=\"menueId(server)\"\n                    [attr.aria-label]=\"'Weitere Aktionen für ' + server.name\"\n                    [cdkMenuTriggerFor]=\"weitere\"\n                  >\n                    <z-icon name=\"more_vert\" />\n                  </button>\n                </div>\n                <ng-template #weitere>\n                  <z-menu>\n                    <button zMenuItem icon=\"content_copy\" (triggered)=\"kopieren.emit(server)\">\n                      Adresse kopieren\n                    </button>\n                    <button zMenuItem icon=\"restart_alt\" (triggered)=\"neustart.emit(server)\">\n                      Neustart\n                    </button>\n                    <!-- Destructive entries sit below the separator and always\n                         open a dialog (Menu README). -->\n                    <z-menu-separator />\n                    <button zMenuItem icon=\"delete\" danger (triggered)=\"loeschen.emit(server)\">\n                      Server löschen\n                    </button>\n                  </z-menu>\n                </ng-template>\n                <!-- #endregion -->\n              }\n            </z-rows>\n          }\n        }\n        <!-- #endregion -->\n        <!-- #region seitenwahl -->\n        <!--\n          The pagination stands alone in its @if: z-panel picks it out of the\n          projected content and puts it in the last row, and a control flow\n          block only reaches a named slot while it holds this single node.\n          z-pagination renders nothing while everything fits on one page.\n        -->\n        @if (zustand() === 'liste') {\n          <z-pagination\n            [(page)]=\"seite\"\n            [pageSize]=\"proSeite\"\n            [total]=\"server().length\"\n            itemLabel=\"Servern\"\n          />\n        }\n        <!-- #endregion -->\n      </z-panel>\n    }\n  `,\n})\nexport class ServerList {\n  private readonly host = inject<ElementRef<HTMLElement>>(ElementRef);\n  private readonly injector = inject(Injector);\n\n  /** The servers to show, already filtered by the page. */\n  readonly server = input.required<readonly BeispielServer[]>();\n\n  /** Which state the list is in. */\n  readonly zustand = input.required<ListenZustand>();\n\n  /** The row itself was clicked: in a real application a routerLink. */\n  readonly oeffnen = output<BeispielServer>();\n\n  /** \"Adresse kopieren\" from the row menu. */\n  readonly kopieren = output<BeispielServer>();\n\n  /** \"Neustart\" from the row menu. */\n  readonly neustart = output<BeispielServer>();\n\n  /** \"Server löschen\" from the row menu. The page asks before it happens. */\n  readonly loeschen = output<BeispielServer>();\n\n  /** \"Server erstellen\" from the empty state. */\n  readonly erstellen = output<void>();\n\n  /** \"Filter zurücksetzen\" when the filter matches nothing. */\n  readonly filterZuruecksetzen = output<void>();\n\n  /** \"Erneut laden\" from the error alert. */\n  readonly erneutLaden = output<void>();\n\n  protected readonly proSeite = PRO_SEITE;\n  protected readonly platzhalter = PLATZHALTER;\n\n  /**\n   * Shared grid for head and rows, so that status, tariff and amount line up:\n   * name, status, tariff, amount, action button (ServerList README). Below\n   * 640px the stylesheet keeps name and status, drops tariff and amount and\n   * keeps the action, so the row menu stays reachable on a phone.\n   */\n  protected readonly spalten = 'minmax(0, 2fr) 128px 96px 96px 40px';\n\n  /**\n   * Current page, clamped instead of reset: it follows the number of pages and\n   * keeps the chosen page as long as that page still exists. Deleting the\n   * seventh server on page two used to throw the reader back to page one; now\n   * only a list that has become too short moves the page, and then no further\n   * than the last page there is.\n   */\n  protected readonly seiten = computed(() =>\n    Math.max(1, Math.ceil(this.server().length / PRO_SEITE)),\n  );\n  protected readonly seite = linkedSignal<number, number>({\n    source: this.seiten,\n    computation: (seiten, vorher) => Math.min(vorher?.value ?? 1, seiten),\n  });\n\n  protected readonly sichtbar = computed(() => {\n    const start = (this.seite() - 1) * PRO_SEITE;\n    return this.server().slice(start, start + PRO_SEITE);\n  });\n\n  protected preis(server: BeispielServer): string {\n    return euro(server.kosten);\n  }\n\n  /** Id of the menu button of a row, so the dialog can name it as its trigger. */\n  protected menueId(server: BeispielServer): string {\n    return `aktionen-${server.id}`;\n  }\n\n  /**\n   * Moves the focus off a row that is about to disappear. The page calls it\n   * before it removes the server, because the menu button that opened the\n   * dialog goes with its row and the focus would otherwise fall to `<body>`.\n   *\n   * It lands on the menu button of the row that takes the place of the removed\n   * one, on the last row's button when the removed row was the last, and on the\n   * main landmark when no row is left.\n   */\n  fokusNachEntfernen(server: BeispielServer): void {\n    const index = Math.max(\n      0,\n      this.sichtbar().findIndex((eintrag) => eintrag.id === server.id),\n    );\n    afterNextRender(\n      () => {\n        const element = this.host.nativeElement;\n        const knoepfe = element.querySelectorAll<HTMLElement>('.z-row__action');\n        const ziel = knoepfe[Math.min(index, knoepfe.length - 1)];\n        (ziel ?? element.closest('main'))?.focus();\n      },\n      { injector: this.injector },\n    );\n  }\n}\n",
  "projects/beispiel-app/tsconfig.app.json": "/* To learn more about Typescript configuration file: https://www.typescriptlang.org/docs/handbook/tsconfig-json.html. */\n/* To learn more about Angular compiler options: https://angular.dev/reference/configs/angular-compiler-options. */\n{\n  \"extends\": \"../../tsconfig.json\",\n  \"compilerOptions\": {\n    \"types\": [],\n    /* The workspace root maps `zenit-ui` to the library sources, which is what\n       library development needs. This application is the proof that the built\n       package works, so it resolves the same specifier to `dist/zenit-ui`, the\n       folder `ng build zenit-ui` writes and `npm pack` would ship. Paths\n       without `baseUrl` are relative to this file. */\n    \"paths\": {\n      \"zenit-ui\": [\"../../dist/zenit-ui\"]\n    }\n  },\n  \"include\": [\"src/**/*.ts\"],\n  \"exclude\": [\"src/**/*.spec.ts\"]\n}\n",
  "angular.json (Auszug)": "\"beispiel-app\": {\n  \"architect\": {\n    \"build\": {\n      \"options\": {\n        \"styles\": [\n          \"dist/zenit-ui/styles/tokens.css\",\n          \"@angular/cdk/overlay-prebuilt.css\",\n          \"dist/zenit-ui/styles/themes.css\",\n          \"dist/zenit-ui/styles/zenit-ui.css\",\n          \"projects/beispiel-app/src/styles.css\"\n        ]\n      }\n    }\n  }\n}"
};
